//! Scenarios on the shared portfolio against an independent implementation in pandas, NumPy and
//! SciPy. The fixture is generated by `scripts/reference/scenarios.py`.

#![allow(clippy::unwrap_used)]

use finalytics::formats::{CsvOptions, fx_from_csv, portfolio_from_csv, prices_from_csv};
use finalytics::risk::{
    HistoricalWindow, ScenarioOptions, ScenarioResult, Shocks, historical_scenario, shock_scenario,
};
use finalytics::{Books, Currency, Date, HoldingKey, MarketData};
use serde_json::Value;

const INSTRUMENTS: &str = include_str!("../../../tests/scenario/instruments.csv");
const TRANSACTIONS: &str = include_str!("../../../tests/scenario/transactions.csv");
const PRICES: &str = include_str!("../../../tests/scenario/prices.csv");
const FX: &str = include_str!("../../../tests/scenario/fx.csv");

fn setup() -> (Books, MarketData) {
    let options = CsvOptions::default();
    let portfolio =
        portfolio_from_csv(Currency::USD, INSTRUMENTS, TRANSACTIONS, None, options).unwrap();
    let mut market = MarketData::new();
    for (id, prices) in prices_from_csv(PRICES, options).unwrap() {
        market = market.with_prices(id, prices);
    }
    for fx in fx_from_csv(FX, options).unwrap() {
        market = market.with_fx(fx.base, fx.quote, fx.rates);
    }
    (Books::build(&portfolio, &market).unwrap(), market)
}

fn fixture() -> Value {
    serde_json::from_str(include_str!("fixtures/scenarios.json")).unwrap()
}

fn label(key: &HoldingKey) -> String {
    match key {
        HoldingKey::Instrument(id) => id.to_string(),
        HoldingKey::Cash(c) => format!("{c} cash"),
    }
}

#[track_caller]
fn close(actual: f64, expected: &Value, what: &str) {
    let expected = expected.as_f64().unwrap();
    assert!(
        (actual - expected).abs() <= 1e-12 * expected.abs().max(1.0),
        "{what}: {actual} against the reference {expected}"
    );
}

fn date(value: &Value) -> Date {
    value.as_str().unwrap().parse().unwrap()
}

/// Compares the parts of a result that every case has.
fn compare(result: &ScenarioResult, expected: &Value) {
    close(
        result.value_before,
        &expected["value_before"],
        "value before",
    );
    close(result.value_after, &expected["value_after"], "value after");
    let holdings = expected["holdings"].as_array().unwrap();
    assert_eq!(result.holdings.len(), holdings.len());
    for (h, e) in result.holdings.iter().zip(holdings) {
        let name = label(&h.holding);
        assert_eq!(name, e["label"].as_str().unwrap());
        close(h.local_return, &e["local_return"], &format!("{name} local"));
        close(
            h.currency_return,
            &e["currency_return"],
            &format!("{name} currency"),
        );
        close(h.total_return, &e["total_return"], &format!("{name} total"));
        close(h.value_after, &e["value_after"], &format!("{name} after"));
    }
    for scheme in &result.groups {
        let groups = expected["groups"][&scheme.scheme].as_array().unwrap();
        assert_eq!(scheme.groups.len(), groups.len());
        for (g, e) in scheme.groups.iter().zip(groups) {
            assert_eq!(g.group, e["group"].as_str().unwrap());
            close(g.change, &e["change"], &format!("{} change", g.group));
            close(
                g.contribution,
                &e["contribution"],
                &format!("{} contribution", g.group),
            );
        }
    }
}

#[test]
fn shocks_match_the_reference() {
    let (books, market) = setup();
    let case = &fixture()["shocks"];
    let shocks: Shocks = serde_json::from_value(case["shocks"].clone()).unwrap();
    let options: ScenarioOptions = serde_json::from_value(case["options"].clone()).unwrap();
    let result = shock_scenario(&books, &market, date(&case["as_of"]), &shocks, &options).unwrap();
    let expected = &case["expected"];
    compare(&result, expected);
    assert_eq!(result.groups.len(), 2);
    for (risk, key) in [
        (&result.risk_before, "risk_before"),
        (&result.risk_after, "risk_after"),
    ] {
        let risk = risk.as_ref().unwrap();
        let e = &expected[key];
        close(risk.volatility, &e["volatility"], key);
        close(risk.value_at_risk, &e["value_at_risk"], key);
        for (c, x) in risk
            .contributions
            .iter()
            .zip(e["components"].as_array().unwrap())
        {
            close(c.component, x, &format!("{key} {}", c.label));
        }
    }
}

#[test]
fn factor_shocks_match_the_reference() {
    let (books, market) = setup();
    for key in ["factors_one", "factors_two", "factors_alone"] {
        let case = &fixture()[key];
        let shocks: Shocks = serde_json::from_value(case["shocks"].clone()).unwrap();
        let result = shock_scenario(
            &books,
            &market,
            date(&case["as_of"]),
            &shocks,
            &ScenarioOptions::default(),
        )
        .unwrap();
        compare(&result, &case["expected"]);
        let expected = case["expected"]["factor_returns"].as_array().unwrap();
        for ((name, f), e) in result.factor_returns.iter().zip(expected) {
            close(*f, e, &format!("{key} {name}"));
        }
    }
}

#[test]
fn historical_replays_match_the_reference() {
    let (books, market) = setup();
    for key in ["historical", "historical_proxy"] {
        let case = &fixture()[key];
        let window: HistoricalWindow = serde_json::from_value(case["window"].clone()).unwrap();
        let result = historical_scenario(
            &books,
            &market,
            date(&case["as_of"]),
            &window,
            &ScenarioOptions::default(),
        )
        .unwrap();
        let expected = &case["expected"];
        compare(&result, expected);
        let path = result.path.as_ref().unwrap();
        let dates: Vec<Date> = expected["path"]["dates"]
            .as_array()
            .unwrap()
            .iter()
            .map(date)
            .collect();
        assert_eq!(path.dates, dates, "{key} dates");
        for (v, e) in path
            .values
            .iter()
            .zip(expected["path"]["values"].as_array().unwrap())
        {
            close(*v, e, &format!("{key} path"));
        }
        let drawdown = path.worst_drawdown.as_ref().unwrap();
        assert_eq!(drawdown.peak, date(&expected["path"]["peak"]));
        assert_eq!(drawdown.trough, date(&expected["path"]["trough"]));
        close(drawdown.depth, &expected["path"]["depth"], "depth");
    }
}
